const res = await fetch("https://app.ninjatop.cloud/api/public/v1/orders", {
  method: "POST",
  headers: {
    "Authorization": "Bearer nk_xxxxxxxx",
    "Content-Type": "application/json",
    "Idempotency-Key": crypto.randomUUID(),
  },
  body: JSON.stringify({ service_id: 12, qty: 1 }),
});
const data = await res.json();
console.log(data.orders[0].id, data.orders[0].phone_number);

const res = await fetch("https://app.ninjatop.cloud/api/public/v1/orders/group", {
  method: "POST",
  headers: {
    "Authorization": "Bearer nk_xxxxxxxx",
    "Content-Type": "application/json",
    "Idempotency-Key": crypto.randomUUID(),
  },
  body: JSON.stringify({ service_ids: [12, 5], qty: 1 }),
});
const data = await res.json();
// Baris dgn phone_number sama = satu nomor yg melayani kedua layanan.
console.log(data.orders.map((o) => o.service_name + ':' + o.phone_number));
